package com.franco.desco.adapter.in.web.pricing;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;
public final class PricingRequests{private PricingRequests(){}@Schema(name="PricingCreateConditionRequest")public record CreateCondition(@NotNull Integer modalidadVentaId,@NotBlank@Size(max=40)String codigo,@NotBlank@Size(max=160)String nombre,@Size(max=300)String descripcion,@PositiveOrZero BigDecimal pesoMinimoG,@PositiveOrZero BigDecimal pesoMaximoG){}@Schema(name="PricingUpdateConditionRequest")public record UpdateCondition(@NotBlank@Size(max=160)String nombre,@Size(max=300)String descripcion,@PositiveOrZero BigDecimal pesoMinimoG,@PositiveOrZero BigDecimal pesoMaximoG){}@Schema(name="PricingDisableRequest")public record Disable(@NotBlank@Size(max=500)String motivo){}@Schema(name="PricingCreatePriceRequest")public record CreatePrice(@NotNull Long campaniaVentaId,Long operativoVentaId,@NotNull Integer variedadPaltaId,@NotNull Long condicionComercialId,@NotNull@Positive BigDecimal precio,@NotBlank@Size(min=3,max=3)String moneda,@NotBlank@Size(max=10)String unidadMedida,@NotNull Instant fechaVigenciaDesde){}@Schema(name="PricingVersionPriceRequest")public record VersionPrice(@NotNull@Positive BigDecimal precio,@NotNull Instant fechaVigenciaDesde){} }
